std::vector<double> Matrix::SumPerColumn() const {
    std::vector<double> result(cols_, 0.0);
    std::transform(
        boost::iterators::make_counting_iterator(0),
        boost::iterators::make_counting_iterator(cols_),
        result.begin(),
        [this](std::size_t c) {
            return std::accumulate(
                boost::iterators::make_counting_iterator(static_cast<std::size_t>(0)),
                boost::iterators::make_counting_iterator(rows_),
                0.0,
                [this, c](double s, std::size_t r) { return s + at(r, c); });
        });
    return result;
}

