std::vector<double> Matrix::SumPerColumn() const {
    std::vector<std::size_t> columns(cols_);
    std::iota(columns.begin(), columns.end(), std::size_t{0});
    std::vector<double> result(cols_, 0.0);
    std::transform(columns.begin(), columns.end(), result.begin(), [this](std::size_t c) {
        std::vector<std::size_t> rows(rows_);
        std::iota(rows.begin(), rows.end(), std::size_t{0});
        return std::accumulate(
            rows.begin(), rows.end(), 0.0,
            [this, c](double s, std::size_t r) { return s + at(r, c); });
    });
    return result;
}

std::vector<double> Matrix::SumPerColumn() const {
    std::vector<std::size_t> columns(cols_);
    std::iota(columns.begin(), columns.end(), std::size_t{0});
    std::vector<double> result(cols_, 0.0);
    std::transform(columns.begin(), columns.end(), result.begin(), [this](std::size_t c) {
        std::vector<std::size_t> rows(rows_);
        std::iota(rows.begin(), rows.end(), std::size_t{0});
        return std::accumulate(
            rows.begin(), rows.end(), 0.0,
            [this, c](double s, std::size_t r) { return s + at(r, c); });
    });
    return result;
}

